 const CSS="/* DreamLantern 105/106: 夜漆 · 红线 · 灯金. Presentation only. */\n.dl-root,.dl-intro{--dl-bg:#100c14;--dl-surface:rgba(25,16,25,.78);--dl-gold:#d8b36b;--dl-light:#f0d398;--dl-red:#9c354a;--dl-ivory:#f3e7d3;--dl-muted:#cbbeb2;color:var(--dl-ivory);font:15px/1.65 'Noto Serif CJK SC','Noto Sans CJK SC','Source Han Serif SC','Microsoft YaHei','PingFang SC',system-ui,serif;box-sizing:border-box;color-scheme:dark}\n.dl-root *,.dl-intro *{box-sizing:border-box}.dl-root [hidden],.dl-intro [hidden]{display:none!important}\n.dl-root button,.dl-intro button,.dl-root a,.dl-root input{font:inherit;touch-action:manipulation;-webkit-tap-highlight-color:transparent}\n.dl-root button,.dl-intro button,.dl-root .dl-link{cursor:pointer;color:#f3e7d3!important;background:rgba(25,16,25,.72)!important;border:1px solid rgba(216,179,107,.3)!important;border-radius:11px;min-height:44px;padding:10px 16px;box-shadow:0 6px 18px #0002;text-decoration:none;display:inline-flex;justify-content:center;align-items:center;gap:8px;transition:transform .18s,border-color .2s}\n.dl-root button:active,.dl-intro button:active{transform:scale(.98)}.dl-root button:focus-visible,.dl-intro button:focus-visible,.dl-root a:focus-visible{outline:2px solid #f0d398;outline-offset:3px}.dl-root button:disabled{opacity:.4;cursor:default}\n.dl-root .dl-primary,.dl-intro .dl-primary{background:linear-gradient(135deg,#c99d5e,#e9c98d)!important;color:#21151b!important;font-weight:700;border-color:#f0d398!important;box-shadow:0 6px 22px #d8b36b16}\n.dl-launch{position:fixed;right:12px;bottom:calc(140px + env(safe-area-inset-bottom,0px));z-index:9998;border-radius:28px!important;font-size:13px!important;box-shadow:0 8px 30px #0005!important;max-width:145px}\n.dl-shade{position:fixed;inset:0;width:100%;height:100vh;height:100dvh;z-index:10000;background:#08050dd9;overflow:hidden;display:flex;justify-content:center;align-items:center;padding:env(safe-area-inset-top,0px) 0 env(safe-area-inset-bottom,0px)}\n.dl-paper{isolation:isolate;background:linear-gradient(160deg,rgba(24,15,28,.96),rgba(15,10,18,.98));width:min(960px,100%);height:min(900px,100%);border:1px solid #d8b36b38;border-radius:22px;display:flex;flex-direction:column;position:relative;box-shadow:0 28px 100px #0008;overflow:hidden}\n.dl-paper:before{content:'';position:absolute;inset:-5%;background-image:var(--dl-current-art,none);background-size:cover;background-position:center;filter:blur(16px);transform:scale(1.05);opacity:.18;z-index:-2;pointer-events:none}\n.dl-paper:after{content:'';position:absolute;inset:0;background-image:var(--dl-paper-texture,none),radial-gradient(ellipse at 90% 0,var(--dl-chapter-accent,#9c354a),transparent 65%);background-size:280px 280px,cover;opacity:.065;z-index:-1;pointer-events:none}\n.dl-head{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:20px 25px;position:relative}.dl-head:after{content:'';height:1px;position:absolute;bottom:0;left:16px;right:16px;background:linear-gradient(90deg,transparent,#d8b36b66,transparent)}\n.dl-brand{font-size:26px;line-height:1.25;letter-spacing:.15em;color:#f0d398}.dl-head small{font-size:10px;letter-spacing:.19em;color:#b8a38c}.dl-close{min-width:44px;padding:6px!important}.dl-body{overflow:auto;overscroll-behavior:contain;padding:22px 26px;flex:1;min-height:0;scrollbar-color:#775344 transparent}\n.dl-state{color:#cbbeb2;font-size:12px;letter-spacing:.06em}.dl-state b{color:#f0d398;font-weight:500}.dl-tabs{display:flex;gap:8px;margin:20px 0 24px}.dl-tabs button{flex:1;padding:8px;border-color:#d8b36b25!important;color:#cbbeb2!important}.dl-tabs .dl-active{background:linear-gradient(135deg,#32131d99,#25121eaa)!important;color:#f0d398!important;border-color:#d8b36b8a!important;box-shadow:inset 0 -2px #d8b36b77}\n.dl-kicker{color:#d8b36b;font-size:10px;letter-spacing:.25em;margin:8px 0}.dl-title{font-size:34px;line-height:1.45;font-weight:400;letter-spacing:.13em;margin:8px 0 12px;color:#f3e7d3}.dl-muted{font-size:13px;color: