e}.dl-door:after{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 50% 80%,#d8b36b13,transparent 60%);pointer-events:none}.dl-door b{font-size:35px;letter-spacing:.2em;font-weight:400}.dl-door span{font-size:11px;color:#cbbeb2;letter-spacing:.08em}.dl-root .dl-door[data-era=modern]{background:linear-gradient(145deg,#32131d99,#19121f)!important}\n.dl-gallery{display:flex;overflow-x:auto;gap:14px;scroll-snap-type:x mandatory;overscroll-behavior-x:contain;touch-action:pan-x pan-y;padding:10px 2px 22px;scrollbar-width:thin;scrollbar-color:#775344 transparent}.dl-card{flex:0 0 min(84vw,310px);scroll-snap-align:center;position:relative;overflow:hidden;border:1px solid rgba(216,179,107,.22);border-radius:21px;background:rgba(25,16,25,.72);text-align:left;min-width:0;box-shadow:0 12px 36px #0005}\n.dl-card img{width:100%;height:220px;object-fit:cover;background:transparent}.dl-card .dl-card-text{padding:19px}.dl-card h3{font-size:26px;font-weight:400;margin:6px 0 12px;color:#f3e7d3;letter-spacing:.1em}.dl-card .dl-badge{font-size:10px;color:#d8b36b;letter-spacing:.06em}.dl-card.dl-current{border-color:rgba(240,211,152,.72);box-shadow:0 0 22px #d8b36b1f}.dl-card button{width:100%;margin-top:8px}\n.dl-memory-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.dl-memory{border:1px solid #d8b36b38;background:rgba(25,16,25,.72);border-radius:18px;overflow:hidden;position:relative;box-shadow:0 12px 36px #0003}.dl-memory img{width:100%;height:205px;object-fit:cover}.dl-memory>div{padding:14px}.dl-memory h3{font-size:20px;letter-spacing:.08em;font-weight:400;margin:0 0 6px}.dl-memory .dl-controls{margin:10px 0 0}.dl-memory button{font-size:12px;padding:7px;min-width:0}.dl-memory.dl-spoiler img{filter:blur(5px);opacity:.35}.dl-memory.dl-spoiler:before{content:'未行之缘 · 锁定';position:absolute;top:80px;left:0;width:100%;text-align:center;z-index:1;color:#f0d398;font-size:12px;letter-spacing:.15em}.dl-spoiler-label{color:#cbbeb2;fo