 function stopVisual(){mediaLayer.clear();dropMedia();view.querySelectorAll('.dl-fx').forEach(e=>e.replaceChildren());}
 let manifestPromise=null;
 function assetIndex(){if(!ASSET_BASE)return Promise.resolve(null);if(!manifestPromise){const abort=new AbortController(),timer=setTimeout(()=>abort.abort(),5000);manifestPromise=fetch(asset('manifest/asset.manifest.json'),{signal:abort.signal,cache:'force-cache'}).then(r=>{if(!r.ok)throw Error('assets unavailable');return r.json();}).catch(()=>null).finally(()=>clearTimeout(timer));}return manifestPromise;}
 function installAssetSkin(){
  root.style.setProperty('--dl-paper-texture',`url("${asset('ui/texture-paper.svg')}")`);
  root.style.setProperty('--dl-foxfire-asset',`url("${asset('fx/foxfire/flame.svg')}")`);
  root.style.setProperty('--dl-thread-asset',`url("${asset('fx/red-thread/thread.svg')}")`);
  root.style.setProperty('--dl-petal-asset',`url("${asset('fx/petals/petal.svg')}")`);
  root.style.setProperty('--dl-mote-asset',`url("${asset('fx/particles/mote.svg')}")`);
  const link=D.createElement('link');link.rel='stylesheet';link.href=asset('ui/dreamlantern.presentation112.css');link.dataset.dreamlantern='cdn-skin';D.head.append(link);disposers.push(()=>link.remove());
 }
 function bindThumbs(){view.querySelectorAll('[data-dl-thumb]').forEach(img=>{
  let stage=0;img.style.objectPosition=MEDIA112.covers.chapters[img.dataset.dlThumb]?.objectPosition||'50% 30%';
  img.onerror=()=>{if(stage++===0)img.src=resolveAsset('ui/brand-background.webp');else if(stage===2)img.src=uri(img.dataset.dlThumb);else img.remove();};
 });}
 function enhanceIntro(intro){
  if(shade.hidden)mediaLayer.mountIntro(intro);
  const c=BY[state()._当前篇章],key=c?.id||'brand';if(intro.dataset.artRequested===key)return;intro.dataset.artRequested=key;
  const url=c&&hasOfficial(c)?resolveAsset(visual(c).officialAssetUrl):resolveAsset('ui/brand-background.webp');
  const scene=intro.querySelector('.dl-scene');scene.style.backgroundImage=`url("${BRAND_BACKGROUND}")`;intro.dataset.mediaStatus='brand-local';
  scene.style.backgroundPosition=c?(visual(c).objectPosition||'50% 42%'):'50% 50%';
  const im=new W.Image();im.referrerPolicy='no-referrer';im.onload=()=>{if(!disposed&&intro.isConnected&&intro.dataset.artRequested===key){scene.style.backgroundImage=`url("${url}")`;intro.dataset.mediaStatus=c&&hasOfficial(c)?'official':'brand';}};im.src=url;
 }
 function makeFx(host,c){/* 112 owns the visible FX DOM within its mobile budget. */}
 function mountMedia(host,c){mediaLayer.mountOpening(root,host,c.id,uri(c.id),lowMotion,memorySource);}
 function favs(){try{const x=JSON.parse(W.localStorage.getItem('hxy_dreamlantern_favorites')||'[]');return Array.isArray(x)?x.filter(v=>BY[v]||v==='MEM_ZHUYE'):[];}catch{return [];}}
 function toggleFav(id){const xs=favs(),next=xs.includes(id)?xs.filter(x=>x!==id):[...xs,id];try{W.localStorage.setItem('hxy_dreamlantern_favorites',JSON.stringify(next));notify(next.includes(id)?'已收藏这一段缘忆。':'已取消收藏。');}catch{notify('此浏览器暂不能保存收藏，回放仍可使用。');}}
 function renderHome(){const s=state(),c=BY[s._当前篇章];view.innerHTML=stateline()+tabs('')+'<p class="dl-kicker">一盏梦灯 · 一页未完的故事</p><h1 class="dl-title">梦灯笼</h1>'+(c?`<p class="dl-muted">当前缘卷 · ${esc(c.title)}<br>故事的脚步，由你决定。</p><div class="dl-controls">${button('replay-current','重温Opening')}${button('next',c.rank===21?'开放沙盒':'下一卷')}</div>`:'<p class="dl-muted">灯下的红线通向前尘，也通向今世。</p><div class="dl-controls">'+button('doors','点亮梦灯','class="dl-primary"')+'</div>')+'<div class="dl-controls">'+button('fx',fxEnabled?'特效 · 已开启':'特效 · 已关闭')+button('motion',lowMotion?'轻动效 · 已开启':'切换轻动效')+'</div>';}
 function renderDoors(){view.innerHTML=stateline()+tabs('chapters')+'<p class="dl-kicker">苦情树下 · 前世今生</p><h1 class="dl-title">缘起何时</h1><p class="dl-muted">选择启程的时代。进入今世后，前尘仅供观忆。</p><div class="dl-doors">'+button('era','<b>前尘</b><span>古代 · 八卷旧事</span>','class="dl-door" data-era="ancient"')+button('era','<b>今世</b><span>现代 · 十三段缘</span>','class="dl-door" data-era="modern"')+'</div>';}
 function label(c){const s=state(),cur=BY[s._当前篇章];return s._当前篇章===c.id?'当前缘卷':!controller.canEnter(c.id)?'历史观忆':cur?'可前往':'由此启程';}
 function renderChapters(){const s=state();view.innerHTML=stateline()+tabs('chapters')+'<p class="dl-kicker">缘卷 · 灯下山河</p><h1 class="dl-title">'+(era==='ancient'?'前尘八卷':'今世十三卷')+'</h1><div class="dl-controls">'+button('era','前尘','data-era="ancient"')+button('era','今世','data-era="modern"')+'</div><p class="dl-muted">左右轻滑，展开景窗。入梦只会向前；过去的缘分可以重温。</p><div class="dl-gallery" role="list">'+CH.filter(c=>c.era===era).map(c=>`<article class="dl-card ${s._当前篇章===c.id?'dl-current':''}" role="listitem"><button class="dl-cover-action" data-action="preview" data-id="${c.id}" aria-label="展开${esc(c.title)} Opening"><img class="dl-thumb" data-dl-thumb="${c.id}" loading="lazy" src="${thumb(c)}" alt="${esc(c.title)} · 景窗"></button><div class="dl-card-text"><span class="dl-badge">${c.id} · ${label(c)}</span><h3>${esc(c.title)}</h3>${button('preview','展开此卷',`data-id="${c.id}"`)}</div></article>`).join('')+'</div>';
  const current=view.querySelector('.dl-current');if(current){const gallery=current.parentElement;gallery.scrollLeft=current.offsetLeft-(gallery.clientWidth-current.clientWidth)/2;}
 }
 function renderMemories(){const s=state(),rank=BY[s._当前篇章]?.rank||0,xs=favs();view.innerHTML=stateline()+tabs('memories')+'<p class="dl-kicker">缘忆 · 不改今生</p><h1 class="dl-title">灯影留痕</h1><p class="dl-muted">收藏与回放只留住画面，不会改变你正走的故事。</p><div class="dl-memory-grid">'+[...CH.map(c=>({...c,memoryId:c.id})),{...BY.A03,title:'竹业·历史观忆',memoryId:'MEM_ZHUYE'}].map(c=>`<article class="dl-memory ${rank&&c.rank>rank?'dl-spoiler':''}"><img class="dl-thumb" data-dl-thumb="${c.id}" loading="lazy" src="${thumb(c)}" alt="${esc(c.title)}"><div><h3>${esc(c.title)}</h3><small class="dl-spoiler-label">${rank&&c.rank>rank?'未行之缘 · 点击自愿预览':'历史观忆'}</small><div class="dl-controls">${button('memory','重温',`data-id="${c.memoryId}"`)}${button('favorite',xs.includes(c.memoryId)?'已收藏':'收藏',`data-id="${c.memoryId}" aria-pressed="${xs.includes(c.memoryId)}"`)}</div></div></article>`).join('')+'</div>';}
 function renderOpening(){const c=BY[preview];if(!c){renderHome();return;}const allowed=!replay&&controller.canEnter(c.id);
  view.innerHTML=stateline()+tabs('')+`<div class="dl-opening"><div class="dl-opening-copy"><p class="dl-kicker">${replay||!allowed?'历史观忆 · 仅回放':c.era==='ancient'?'前尘 · 缘卷'+c.id.slice(1):'今世 · 缘卷'+c.id.slice(1)}</p><h2>${memorySource?"竹业 · 历史观忆":esc(c.title)}</h2><p class="dl-muted"><span data-media-label>灯影载入中</span></p><a href="${esc(visual(c).sourcePage||c.officialUrl)}" target="_blank" rel="noopener">${esc(c.officialLinkLabel||'查看官方来源')} ↗</a><div class="dl-controls">${allowed?button('enter','由此入梦',`class="dl-primary" data-id="${c.id}"`):''}${button('favorite',favs().includes(c.id)?'已收藏':'收藏',`data-id="${c.id}"`)}${button('back','返回')}</div></div></div>`;
  mountMedia(view.querySelector('.dl-opening'),c);
 }
 function ensureMusic(){if(music||!W.__DreamLanternMusic)return;try{
  const box=root.querySelector('.dl-music');music=W.__DreamLanternMusic.attach(box,CATALOGUE);
  const album=D.createElement('div');album.className='dl-album';album.innerHTML='<p class="dl-kicker">Lethe · 狐妖小红娘</p><a class="dl-link" href="https://163cn.tv/bi16o77e" target="_blank" rel="noopener">打开完整专辑 ↗</a>';box.prepend(album);
  const pending=MUSIC_SOURCE.pendingTracks||[];if(pending.length){const p=D.createElement('p');p.className='dl-muted dl-pending-tracks';p.textContent='曲目核验中：'+pending.map(x=>x.title).join('、')+'。请先打开完整专辑收听。';box.append(p);}
 }catch{root.querySelector('.dl-music').textContent='缘音暂不可用，请在网易云官方App播放。';}}
 function render(){if(disposed)return;stopVisual();const musicBox=root.querySelector('.dl-music');musicBox.hidden=page!=='music';view.hidden=false;
  if(page==='home')renderHome();else if(page==='doors')renderDoors();else if(page==='chapters')renderChapters();else if(page==='memories')renderMemories();else if(page==='opening')renderOpening();else if(page==='music'){view.innerHTML=stateline()+tabs('music');ensureMusic();}
  if(page==='doors'){mediaLayer.mountEraGate(root,lowMotion);}mediaLayer.mountGlobal(root);updateChapterBackground();bindThumbs();applyMotion();root.querySelectorAll('button[data-action="enter"]').forEach(b=>b.disabled=busy);
 }
 function open(next='home'){D.querySelectorAll('.dl-intro').forEach(e=>e.classList.add('dl-muted-scene'));mediaLayer.showIntro(false);returnFocus=D.activeElement;shade.hidden=false;page=next;render();root.querySelector('.dl-paper').focus();}
 function close(){D.querySelectorAll('.dl-intro').forEach(e=>e.classList.remove('dl-muted-scene'));shade.hidden=true;stopVisual();returnFocus?.focus?.();}
 async function enter(id){if(busy)return;busy=true;render();try{await controller.enter(id);page='home';render();notify('缘卷已展开。故事由你的下一句落笔。');
   // Fill an ordinary action; never auto-send or impersonate the player.
   const c=BY[id],input=D.querySelector('#send_textarea');if(input&&!input.value){input.value=`我选择从${c.era==='ancient'?'古代':'现代'}「${c.title}」开局，请依据当前启用时间线展开场景，并保留我的玩家设定。`;input.dispatchEvent(new W.Event('input',{bubbles:true}));}
   mountIntro();mountMini();
  }catch(e){notify(e.message||'入梦暂未成功，请重试。');}finally{busy=false;root.querySelectorAll('[data-action="enter"]').forEach(b=>b.disabled=false);}}
 function playOpening(id,options={}){if(!BY[id])return false;preview=id;memorySource=options.memoryId||null;replay=options.mode==='replay'||options.allowEnter===false;open('opening');return true;}
 function click(e){const b=e.target.closest('[data-action]');if(!b||!(root.contains(b)||b.closest('.dl-intro')))return;const a=b.dataset.action,id=b.dataset.id;
  if(a==='open')open('doors');else if(a==='close')close();else if(a==='doors'){open('doors');}else if(a==='era'){const locked=b.dataset.era==='ancient'&&!!state()._现代锁定;if(b.classList.contains('dl-door')){if(!mediaLayer.previewEra(b,locked))return;if(locked)return;}era=b.dataset.era;page='chapters';render();}else if(['chapters','memories','music','home'].includes(a)){page=a;if(a==='chapters')era=state()._时代==='现代'?'modern':era;render();}
  else if(a==='preview')playOpening(id,{mode:'enter',allowEnter:controller.canEnter(id)});
  else if(a==='enter')void enter(id);
  else if(a==='back'){page=replay?'memories':'chapters';render();}
  else if(a==='replay-current')playOpening(state()._当前篇章,{mode:'replay',allowEnter:false});
  else if(a==='memory')playOpening(id==='MEM_ZHUYE'?'A03':id,{mode:'replay',allowEnter:false,memoryId:id==='MEM_ZHUYE'?id:null});
  else if(a==='favorite'){toggleFav(id);b.textContent=favs().includes(id)?'已收藏':'收藏';b.setAttribute('aria-pressed',String(favs().includes(id)));}
  else if(a==='next'){const cur=BY[state()._当前篇章];if(cur?.rank===21){notify('当前已是新北山篇，继续在现有世界中自由探索。');return;}const next=CH.find(c=>c.rank===(cur?.rank||0)+1);if(next)playOpening(next.id,{mode:'enter',allowEnter:true});}
  else if(a==='fx'){fxEnabled=!fxEnabled;try{W.localStorage.setItem('hxy_dreamlantern_preferences',JSON.stringify({...getPrefs(),presentation115:1,fxEnabled}));}catch{}applyMotion();}
  else if(a==='motion'){lowMotion=!lowMotion;try{W.localStorage.setItem('hxy_dreamlantern_preferences',JSON.stringify({...getPrefs(),presentation115:1,fxEnabled,lowMotion}));}catch{}render();}
 }
 D.addEventListener('click',click);disposers.push(()=>D.removeEventListener('click',click));
 function key(e){if(shade.hidden)return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const els=[...root.querySelectorAll('.dl-paper button,.dl-paper a[href],.dl-paper input,.dl-paper summary')].filter(x=>!x.disabled&&x.getClientRects().length);const first=els[0],last=els.at(-1);if(e.shiftKey&&(D.activeElement===first||D.activeElement===root.querySelector('.dl-paper'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&D.activeElement===last){e.preventDefault();first?.focus();}}}
 D.addEventListener('keydown',key);disposers.push(()=>D.removeEventListener('keydown',key));
 // The 0-floor is a lightweight host. No waiting for MVU, network or music.
 function mountIntro(){
  const box=D.querySelector('#chat > .mes[mesid="0"] .mes_text');if(!box)return;
  let m;try{m=getChatMessages(0)?.[0];}catch{}
  if(m?.role!=='assistant'||!String(m.message).includes('[DREAM_LANTERN_OPENING_FLOW]')){box.querySelector('.dl-intro')?.remove();return;}
  if(box.querySelector('.dl-intro')){const b=box.querySelector('.dl-intro button');b.dataset.action=state()._时代==='未选择'?'doors':'open';b.textContent='展开狐妖手札';enhanceIntro(box.querySelector('.dl-intro'));return;}
  box.querySelector('.dl-opening-seed')?.remove();const intro=D.createElement('section');intro.className='dl-intro';intro.innerHTML=`<div class="dl-scene" style="background-image:url('${BRAND_BACKGROUND}')"></div><div class="dl-intro-content"><div class="dl-ember" aria-hidden="true"></div><p class="dl-intro-overline">狐妖小红娘 · DREAM LANTERN</p><h1>梦灯笼</h1><p>前尘有梦，今世有灯。<br>红线未尽，缘起涂山。</p>${button(state()._时代==='未选择'?'doors':'open','展开狐妖手札','class="dl-primary"')}<div class="dl-small">狐妖小红娘 · 缘卷 / 缘忆 / 缘音</div></div>`;box.append(intro);enhanceIntro(intro);applyMotion();
 }
 function mountMini(){
  D.querySelectorAll('.dl-mini').forEach(e=>e.remove());const s=state();if(!BY[s._当前篇章])return;
  let id;try{id=getLastMessageId();}catch{return;}if(id===0)return;
  let m;try{m=getChatMessages(id)?.[0];}catch{}if(m?.role!=='assistant')return;
  const box=D.querySelector(`#chat > .mes[mesid="${Number(id)}"] .mes_text`);if(!box)return;const bar=D.createElement('div');bar.className='dl-mini';bar.textContent='✧ 梦灯笼 · '+s._时代+' / '+BY[s._当前篇章].title;box.append(bar);
 }
 function schedule(){if(disposed)return;clearTimeout(refreshTimer);refreshTimer=later(()=>{mountIntro();mountMini();if(!shade.hidden)render();void controller.heal().catch(e=>notify(e.message));},100);}
 function on(name,fn){if(!name||typeof eventOn!=='function')return;const handle=eventOn(name,fn);disposers.push(()=>{if(handle?.stop)handle.stop();else if(typeof eventRemoveListener==='function')eventRemoveListener(name,fn);});}
 function chatChange(){epoch++;busy=false;page='home';close();music?.dispose();music=null;root.querySelector('.dl-music').replaceChildren();D.querySelectorAll('.dl-intro,.dl-mini').forEach(e=>e.remove());schedule();}
 if(typeof tavern_events!=='undefined'){
  on(tavern_events.CHAT_CHANGED,chatChange);for(const k of ['MESSAGE_SWIPED','MESSAGE_UPDATED','CHARACTER_MESSAGE_RENDERED','MESSAGE_DELETED'])on(tavern_events[k],schedule);
 }
 async function bindMvu(){try{await waitGlobalInitialized('Mvu');if(disposed)return;
  // Three underscore fields are script-owned. A model update cannot change them.
  on(Mvu.events.VARIABLE_UPDATE_ENDED,(data,before)=>{if(before?.stat_data&&data?.stat_data)for(const k of ['_时代','_当前篇章','_现代锁定'])data.stat_data[k]=before.stat_data[k];schedule();});
  on(Mvu.events.VARIABLE_INITIALIZED,schedule);schedule();
 }catch(e){notify('变量系统暂未就绪；可以先浏览缘卷与缘忆。');}}
 function musicReady(){if(page==='music')ensureMusic();}W.addEventListener('dreamlantern-music-ready',musicReady);disposers.push(()=>W.removeEventListener('dreamlantern-music-ready',musicReady));
 function dispose(){if(disposed)return;disposed=true;epoch++;stopVisual();mediaLayer.dispose();music?.dispose();disposers.forEach(f=>{try{f();}catch{}});timers.forEach(clearTimeout);clearTimeout(refreshTimer);root.remove();style.remove();D.querySelectorAll('.dl-intro,.dl-mini').forEach(e=>e.remove());if(W.DreamLantern===api)delete W.DreamLantern;}
 const api={playOpening,refresh:schedule,dispose,open,controller,manifest:MANIFEST};W.DreamLantern=api;
 window.addEventListener('pagehide',dispose,{once:true});disposers.push(()=>window.removeEventListener('pagehide',dispose));
 function visibility(){mediaLayer.visibility(D.hidden);root.classList.toggle('dl-suspended',D.hidden);D.querySelectorAll('.dl-intro').forEach(e=>e.classList.toggle('dl-suspended',D.hidden));}
 D.addEventListener('visibilitychange',visibility);disposers.push(()=>D.removeEventListener('visibilitychange',visibility));
 installAssetSkin();mountIntro();mountMini();applyMotion();void bindMvu();void loadVisualOverrides();
})();

